import sys

def execute_program():
    input_val = int(sys.stdin.read().strip())
    print(compute_result(input_val))

def compute_result(n):
    max_size = int(4e5)
    high = [0] * max_size
    low = [0] * max_size
    for i in range(1, max_size):
        low[i] = i
        high[i] = n // i
    prime_flags = [True] * max_size
    prime_flags[0] = False
    prime_flags[1] = False

    prime_list = []
    for i in range(2, max_size):
        if not prime_flags[i]:
            continue
        prime_list.append(i)
        for j in range(i * 2, max_size, i):
            prime_flags[j] = False

    for index, p in enumerate(prime_list):
        p_sq = p * p
        for i in range(1, max_size):
            if n // i < p_sq:
                break
            val = p * i
            if val < max_size:
                high[i] -= (high[val] - (index + 1))
            else:
                n_div_i = n // i
                low_idx = n_div_i // p
                low[low_idx] -= (low[low_idx] - (index + 1))
        for i in range(max_size - 1, p_sq - 1, -1):
            low[i] -= low[i // p] - (index + 1)

    result_count = 0
    for p in prime_list:
        if p * p > n:
            break
        if p * p * p <= n and p * p * p > 0:
            result_count += 1
        if n // p > p:
            if p < max_size:
                result_count += high[p] - low[p]
            else:
                result_count += low[n // p] - low[p]
    return result_count

if __name__ == "__main__":
    execute_program()

